"""Arithmetic helpers."""


def add(a: int, b: int) -> int:
    return a + b


def subtract(a: int, b: int) -> int:
    return a - b


def divide(a: int, b: int) -> float:
    return a / b


def power(base: int, exponent: int) -> int:
    return base ** exponent
